#!/usr/bin/env bun
/** bun contract [--check]: the contract between the database, the API and the app (D80), generated so a limit lives once.
 *  Writes the API's database types from supabase/types.ts, the app's limits and lists from the API's schemas
 *  (api/src/contract.ts), the fake's sample answers, which the app's decoders read in ContractTests, and the plan cases'
 *  copy for DomainTests. --check writes
 *  nothing: it names each generated file that is stale, missing or left over, and exits 1. */
import { readdir } from "node:fs/promises";
import { join, relative } from "node:path";

export type Contract = { limits: Record<string, number>; lists: Record<string, string[]> };

const ROOT = join(import.meta.dir, "..");
const DATABASE = "api/src/generated/database.ts";
const SWIFT = "ios/TutorCentralKit/Sources/Domain/Generated/APIContract.swift";
const SAMPLES = "ios/TutorCentralKit/Tests/DataTests/Contract";
/** The shared plan cases (written from Domain's rules, read by DomainTests and the API's port), copied into the test
 *  target, which cannot reach a file outside its directory. */
const PLAN_CASES = "tools/contract/plan-cases.json";
const PLAN_CASES_COPY = "ios/TutorCentralKit/Tests/DomainTests/Cases/plan-cases.json";

export function databaseFile(types: string): string {
  return `// Generated by bun contract from supabase/types.ts. Do not edit.\n${types}`;
}

export function renderSwift(c: Contract): string {
  const lines = [
    "// Generated by bun contract from api/src/schemas.ts. Do not edit.",
    "// swiftformat:disable all",
    "// swiftlint:disable all",
    "",
    "/// The API's limits and lists (api/src/contract.ts): a body the app sends keeps within them.",
    "public enum APIContract {",
    ...Object.entries(c.limits).map(([name, value]) => `    public static let ${name} = ${value}`),
    ...Object.entries(c.lists).map(([name, values]) => `    public static let ${name} = [${values.map((v) => JSON.stringify(v)).join(", ")}]`),
    "}",
    "// swiftlint:enable all",
    "",
  ];
  return lines.join("\n");
}

function sorted(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sorted);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.keys(value).sort().map((k) => [k, sorted((value as Record<string, unknown>)[k])]));
  }
  return value;
}

export function renderSample(value: unknown): string {
  return `${JSON.stringify(sorted(value), null, 2)}\n`;
}

/** The API's contract and samples, read in the API's own package so its imports resolve as they do there. */
async function fromAPI(): Promise<{ contract: Contract; samples: Record<string, unknown> }> {
  const p = Bun.spawn(
    ["bun", "-e", 'import { contract, samples } from "./src/contract.ts"; console.log(JSON.stringify({ contract: contract(), samples: samples() }))'],
    { cwd: join(ROOT, "api"), stdout: "pipe", stderr: "pipe" },
  );
  const out = await new Response(p.stdout).text();
  if ((await p.exited) !== 0) throw new Error(`api/src/contract.ts did not run: ${await new Response(p.stderr).text()}`);
  return JSON.parse(out);
}

/** Every generated file by its path from the repository's root. */
export async function expected(): Promise<Map<string, string>> {
  const { contract, samples } = await fromAPI();
  const files = new Map<string, string>();
  files.set(DATABASE, databaseFile(await Bun.file(join(ROOT, "supabase/types.ts")).text()));
  files.set(SWIFT, renderSwift(contract));
  for (const [kind, answer] of Object.entries(samples)) files.set(`${SAMPLES}/${kind}.json`, renderSample(answer));
  files.set(PLAN_CASES_COPY, await Bun.file(join(ROOT, PLAN_CASES)).text());
  return files;
}

async function listed(root: string, dir: string): Promise<string[]> {
  try {
    const names = await readdir(join(root, dir), { recursive: true, withFileTypes: true });
    return names.filter((n) => n.isFile()).map((n) => relative(root, join(n.parentPath, n.name)));
  } catch {
    return [];
  }
}

/** The paths that differ from what is expected, are missing, or sit in a generated directory unasked for. */
export async function stale(root: string, files: Map<string, string>, dirs: string[]): Promise<string[]> {
  const out: string[] = [];
  for (const [path, content] of files) {
    const file = Bun.file(join(root, path));
    if (!(await file.exists()) || (await file.text()) !== content) out.push(path);
  }
  for (const dir of dirs) for (const path of await listed(root, dir)) if (!files.has(path)) out.push(path);
  return out;
}

if (import.meta.main) {
  const files = await expected();
  if (process.argv.includes("--check")) {
    const paths = await stale(ROOT, files, [SAMPLES]);
    if (paths.length > 0) {
      console.error(`the contract is stale; run bun contract:\n${paths.map((p) => `  - ${p}`).join("\n")}`);
      process.exit(1);
    }
    console.log("the contract is current");
  } else {
    for (const path of await listed(ROOT, SAMPLES)) if (!files.has(path)) await Bun.file(join(ROOT, path)).delete();
    for (const [path, content] of files) await Bun.write(join(ROOT, path), content);
    console.log(`wrote ${files.size} files`);
  }
}
